const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '图上两地距离 6 厘米' },
      { kind: 'text', payload: '实际距离 150000 厘米' },
      { kind: 'text', payload: '比例尺 1:25000' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = W * 0.12;
    var x0 = margin;
    var x1 = W - margin;
    var y = H * 0.62;
    var minor = H * 0.035;
    var major = H * 0.065;
    var ink = '#1F2A44';

    var seg = [['M', x0, y], ['L', x1, y]];

    var ticks = [];
    for (var i = 0; i <= 6; i++) {
      var x = x0 + (x1 - x0) * i / 6;
      var h = (i === 0 || i === 6) ? major : minor;
      ticks.push(['M', x, y - h]);
      ticks.push(['L', x, y + h]);
    }

    var dy = y - H * 0.20;
    var mark = H * 0.03;
    var dim = [];
    dim.push(['M', x0, dy]);
    dim.push(['L', x1, dy]);
    dim.push(['M', x0, dy - mark]);
    dim.push(['L', x0, dy + mark]);
    dim.push(['M', x1, dy - mark]);
    dim.push(['L', x1, dy + mark]);
    dim.push(['M', x0, y - major]);
    dim.push(['L', x0, dy + mark]);
    dim.push(['M', x1, y - major]);
    dim.push(['L', x1, dy + mark]);

    var cx = (x0 + x1) / 2;

    return {
      schemaVersion: 1,
      sceneId: 'scale-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'dim', commands: dim },
        { id: 'segment', commands: seg },
        { id: 'ticks', commands: ticks }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'dim', fill: ink, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'segment', fill: ink, stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'ticks', fill: ink, stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: dy - H * 0.035 }, hAlign: 'center', vAlign: 'bottom', color: ink },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: y + major + H * 0.05 }, hAlign: 'center', vAlign: 'top', color: ink },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: W / 2, y: H * 0.12 }, hAlign: 'center', vAlign: 'middle', color: ink }
        ]
      }
    };
  }
};
